  // Sun
  brush.fill("#ffcc00", 100);
  brush.beginShape();
  brush.vertex(200, 100);
  brush.vertex(250, 100);
  brush.vertex(250, 150);
  brush.vertex(200, 150);
  brush.endShape(true);
}
